 data=json.loads(verification.read_text());assert data['status']=='passed',data['status'];source=Path(data['cases'][-1]['folder']);label='two_metre_initial_solution';out=ROOT/'deliverables/controlled_jump_pilot'/label;subprocess.run([sys.executable,str(ROOT/'scripts/prepare_control_jump_review.py'),str(source),'--label',label],check=True)
